/* Original Studigo experimental level. No quiz screens or external runtime services. */
(()=>{'use strict';
const $=s=>document.querySelector(s),W=7600,FLOOR=421,C=[0xd6e2ef,0xd6e2ef,0xd6e2ef,0xb8f5bf,0xb8d5ff],held=new Set(),events=[];
let scene,mode='intro',auto=false,weapon=1,unlocked={1:true,3:false,4:false},active=0,clock=0,health=5,checkpoint=130,ammo=0,orbChance=0,audio,paused=false;
const p={x:130,y:FLOOR,vy:0,face:1,ground:true,inv:0,fire:0,land:0},drops=[{x:1520,n:3,attempt:0,status:'ready',loaded:0},{x:3440,n:4,attempt:0,status:'ready',loaded:0}],platforms=[{x:500,y:350,w:180},{x:990,y:318,w:150},{x:1880,y:345,w:220},{x:2560,y:325,w:170},{x:3110,y:345,w:190},{x:4030,y:335,w:230},{x:4700,y:350,w:160},{x:5810,y:333,w:170},{x:6240,y:352,w:160}];
let shots=[],hazards=[],particles=[],trial=null,fireCD=0,jump=false,use=false,fireEdge=false,noticeEnd=0,boss=null,mini=null,won=false,hitStop=0;
function log(type,data={}){events.push({type,t:Math.round(active*100)/100,...data})}
function tone(f=400,d=.12){try{audio||=new(window.AudioContext||window.webkitAudioContext)();audio.resume();let o=audio.createOscillator(),g=audio.createGain();o.type='triangle';o.frequency.setValueAtTime(f,audio.currentTime);o.frequency.exponentialRampToValueAtTime(f*.5,audio.currentTime+d);g.gain.setValueAtTime(.055,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+d)}catch(e){}}
function say(t,d=2.5){$('#notice').textContent=t;noticeEnd=clock+d}
function burst(x,y,c,count=16){for(let i=0;i<count;i++){let a=Math.random()*6.28,v=50+Math.random()*170;particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:.4+Math.random()*.4,c})}}
function hud(){ $('#hearts').textContent='♥ '.repeat(health)+'♡ '.repeat(5-health);for(let n of[1,3,4]){$('#w'+n).classList.toggle('on',weapon===n);$('#w'+n).disabled=!unlocked[n];$('#w'+n+' small').textContent=n===1?'1':'×'+n+(unlocked[n]?'':' ·')}$('#auto small').textContent='AUTO '+(auto?'ON':'OFF');$('#auto').classList.toggle('on',auto);$('#ammo').innerHTML=boss&&p.x>6550?Array.from({length:5},(_,i)=>'<i class="'+(i<ammo?'loaded':'')+'"></i>').join(''):'';$('#bossbar').hidden=!(p.x>6550&&boss.hp>0);$('#bossbar progress').value=boss?boss.hp:50;}
function select(n){if(unlocked[n]){weapon=n;hud();tone(300+n*90)}}
function clear(){held.clear();jump=use=fireEdge=false}
for(let id of['left','right','fire']){let el=$('#'+id);el.onpointerdown=e=>{e.preventDefault();el.setPointerCapture(e.pointerId);held.add(id);if(id==='fire')fireEdge=true;tone(150,.02)};el.onpointerup=el.onpointercancel=e=>held.delete(id)}
$('#jump').onpointerdown=e=>{e.preventDefault();jump=true};$('#use').onpointerdown=e=>{e.preventDefault();use=true};for(let n of[1,3,4])$('#w'+n).onclick=()=>select(n);$('#auto').onclick=()=>{auto=!auto;hud()};
function pause(){if(mode==='intro'||won)return;paused=!paused;clear();$('#pause').textContent=paused?'▶':'Ⅱ';say(paused?'PAUSED':'',1);log('pause',{paused})}$('#pause').onclick=pause;
addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp',' ','f','e','1','3','4','q','Escape'].includes(e.key))e.preventDefault();if(e.repeat)return;if(e.key==='ArrowLeft'||e.key==='a')held.add('left');if(e.key==='ArrowRight'||e.key==='d')held.add('right');if(e.key==='ArrowUp'||e.key===' '||e.key==='w')jump=true;if(e.key==='f'){held.add('fire');fireEdge=true}if(e.key==='e')use=true;if(['1','3','4'].includes(e.key))select(+e.key);if(e.key==='q')$('#auto').click();if(e.key==='Escape')pause()});addEventListener('keyup',e=>{if(['ArrowLeft','a'].includes(e.key))held.delete('left');if(['ArrowRight','d'].includes(e.key))held.delete('right');if(e.key==='f')held.delete('fire')});addEventListener('blur',()=>{clear();if(mode==='play'&&!paused)pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&mode==='play'&&!paused)pause()});
function resize(){let s=getComputedStyle(document.body),l=parseFloat(s.paddingLeft)||0,r=parseFloat(s.paddingRight)||0,t=parseFloat(s.paddingTop)||0,b=parseFloat(s.paddingBottom)||0,w=innerWidth-l-r,h=innerHeight-t-b;$('#stage').style.cssText=`left:${l+w/2}px;top:${t+h/2}px;transform:translate(-50%,-50%) scale(${Math.min(w/960,h/540)})`}addEventListener('resize',resize);resize();
$('#start').onclick=()=>{if(won){location.reload();return}mode='play';$('#cover').hidden=true;tone(650);say('Follow the lanterns →');log('start')};
function groups(d){return [4,3,5,2,6,7,8,9,10,1][d.attempt%10]}
function activate(d){if(d.status!=='ready'||trial)return;trial=d;d.status='trial';d.loaded=0;auto=false;hud();say('One burst fills one group. Pull the lever when full.',5);tone(780);log('drop-open',{factor:d.n,attempt:d.attempt,groups:groups(d),representation:d.attempt%2?'rings':'array'})}
function fail(d){d.status='cooldown';d.readyAt=active+20;d.attempt++;trial=null;burst(d.x,280,0x8ca3bd,24);tone(130,.3);say('The sparks drift away…',1.6);log('drop-failed',{factor:d.n,readyAt:d.readyAt})}
function commit(){if(!trial)return;let d=trial;if(d.loaded!==groups(d)){fail(d);return}unlocked[d.n]=true;weapon=d.n;d.status='earned';trial=null;checkpoint=d.x-100;health=5;burst(d.x,280,C[d.n],65);scene.cameras.main.flash(140,160,215,180);tone(1046,.4);say('×'+d.n+' BURST UNLOCKED',3);log('unlock',{factor:d.n});hud()}
function hurt(){if(p.inv>0||won)return;health--;p.inv=1.8;burst(p.x,p.y-40,0xffb3a0);scene.cameras.main.shake(130,.004);tone(110,.2);log('hurt',{health});if(health<=0){health=5;p.x=checkpoint;p.y=FLOOR;p.vy=0;hazards=[];if(trial)fail(trial);say('Back on your feet!',2);log('checkpoint',{x:checkpoint})}hud()}
class Level extends Phaser.Scene{
 preload(){for(let n of['observatory','platform','core','spark'])this.load.image(n,'../assets/'+n+'.png');this.load.spritesheet('dragon','../assets/dragon.png',{frameWidth:128,frameHeight:128});this.load.spritesheet('guardian','../assets/guardian.png',{frameWidth:256,frameHeight:256});}
 create(){scene=this;this.cameras.main.setBounds(0,0,W,540);this.bg=this.add.tileSprite(480,270,960,540,'observatory').setTileScale(2).setScrollFactor(0);this.back=this.add.graphics();for(let x=0;x<W;x+=240)this.add.image(x,FLOOR,'platform').setOrigin(0).setDisplaySize(242,48).setTint(0x75899d);for(let q of platforms)this.add.image(q.x,q.y,'platform').setOrigin(0).setDisplaySize(q.w,24);this.g=this.add.graphics().setDepth(4);this.hero=this.add.sprite(p.x,p.y+7,'dragon',6).setOrigin(.5,1).setDisplaySize(136,136).setDepth(5);this.fx=this.add.graphics().setDepth(7);this.labels=[];this.enemies=[];let packs=[[730,3],[1100,3],[2180,3],[2390,3],[2770,4],[3010,4],[3940,4],[4330,3],[4630,4],[5950,3],[6230,4]];for(let [x,n]of packs)for(let i=0;i<n;i++){let e={x:x+i*38,y:365-(i%2)*30,hp:1,home:x+i*38,pack:n};e.sprite=this.add.sprite(e.x,e.y,'guardian',0).setDisplaySize(66,66).setTint(n===3?0xb8d7bd:0xb2c7e9).setDepth(3);this.enemies.push(e)}for(let d of drops){d.sprite=this.add.image(d.x,300,'core').setDisplaySize(46,46).setDepth(5);d.label=this.add.text(d.x,228,'',{fontFamily:'monospace',fontSize:16,color:'#d5edc1',stroke:'#06111f',strokeThickness:4}).setOrigin(.5).setDepth(6)}
 mini={x:5280,hp:6,max:6,n:3,hit:0,clock:0};boss={x:7210,hp:50,max:50,n:3,hit:0,clock:0,orb:null};for(let b of[mini,boss]){b.sprite=this.add.sprite(b.x,402,'guardian',0).setOrigin(.5,1).setDisplaySize(b===boss?300:225,b===boss?300:225).setDepth(3)}if(this.game.renderer.type===Phaser.WEBGL)boss.sprite.preFX.addColorMatrix().grayscale(1);this.pickups=[2450,4200,6090].map(x=>({x,taken:false,sprite:this.add.image(x,363,'core').setDisplaySize(23,23).setTint(0xffb5ae)}));
 for(let [x,title]of[[280,'THE MOON ROAD'],[1510,'WHISPER GROVE'],[3400,'FOUR WINDS'],[5160,'THE WATCHER'],[6880,'CORE CLASH']])this.add.text(x,155,title,{fontFamily:'monospace',fontSize:18,letterSpacing:3,color:'#adc5cc',stroke:'#0c1b2b',strokeThickness:5}).setAlpha(.7);
 window.gameState=()=>({mode:won?'victory':paused?'paused':mode,x:p.x,y:p.y,health,checkpoint,weapon,unlocked:{...unlocked},active,ammo,orbChance,trial:trial?{factor:trial.n,groups:groups(trial),loaded:trial.loaded}:null,drops:drops.map(d=>({x:d.x,n:d.n,status:d.status,attempt:d.attempt,readyAt:d.readyAt})),mini:{hp:mini.hp,n:mini.n},boss:{hp:boss.hp,n:boss.n,orb:boss.orb?{...boss.orb}:null}});window.levelEvents=()=>events.slice();hud();}
 fire(){p.fire=.14;fireCD=.32;if(trial){if(fireEdge){trial.loaded++;burst(trial.x,275,C[trial.n],trial.n*4);tone(350+trial.loaded*80);log('group-loaded',{factor:trial.n,groups:trial.loaded});if(trial.loaded>groups(trial))fail(trial)}return}
 let near=drops.find(d=>d.status==='ready'&&Math.abs(d.x-p.x)<220);if(near){activate(near);return}
 let b=p.x>6550?boss:p.x>4900&&mini.hp>0?mini:null;
 if(b===boss&&boss.orb&&Math.abs(p.x-boss.orb.x)<550){let o=boss.orb;if(weapon===o.n){o.loaded++;burst(o.x,290,C[o.n],o.n*5);tone(600);if(o.loaded>=o.groups){ammo=5;boss.orb=null;say('POWER LOADED · 5 SHOTS',2);burst(p.x,p.y-45,0xffe6a3,45);log('power-loaded');}}else{tone(160);burst(o.x,290,0x859bac,6)}hud();return}
 log('volley',{weapon,count:weapon});const emp=b===boss&&ammo>0;if(emp)ammo--;let targets=this.enemies.filter(e=>e.hp>0&&Math.abs(e.x-p.x)<530&&(e.x-p.x)*p.face>-30).sort((a,b)=>Math.abs(a.x-p.x)-Math.abs(b.x-p.x));let count=weapon;for(let i=0;i<count;i++){let tx=p.x+p.face*700,ty=p.y-46+(i-(count-1)/2)*45,target=targets[i];if(target){tx=target.x;ty=target.y}if(b&&b.hp>0){tx=b.x-20;ty=b===boss?265:305}let x=p.x+p.face*43,y=p.y-47,dx=tx-x,dy=ty-y,len=Math.hypot(dx,dy);shots.push({x,y,vx:dx/len*760,vy:dy/len*760,life:1.4,n:weapon,emp,lead:i===0,b})}burst(p.x+p.face*45,p.y-45,emp?0xffe6a3:C[weapon],8);tone(emp?160:330+weapon*50,.08);hud();}
 update(time,delta){let dt=Math.min(.033,delta/1000);if(mode==='play'&&!paused&&!won){clock+=dt;active+=dt;if(hitStop>0)hitStop-=dt;else this.step(dt)}this.draw(dt);}
 step(dt){if(clock>noticeEnd)$('#notice').textContent='';p.inv=Math.max(0,p.inv-dt);p.fire=Math.max(0,p.fire-dt);p.land=Math.max(0,p.land-dt);let dir=+held.has('right')-+held.has('left');if(dir)p.face=dir;let oldY=p.y;p.x+=dir*285*dt;if(jump&&p.ground){p.vy=-470;p.ground=false;tone(520);burst(p.x,p.y,0x93b4c1,7)}jump=false;p.vy+=1150*dt;p.y+=p.vy*dt;p.ground=false;let floor=FLOOR;for(let q of platforms)if(p.x>q.x-8&&p.x<q.x+q.w+8&&oldY<=q.y+3&&p.y>=q.y&&p.vy>=0)floor=Math.min(floor,q.y);if(p.y>=floor){if(p.vy>160){p.land=.12;burst(p.x,floor,0x8296aa,8)}p.y=floor;p.vy=0;p.ground=true}p.x=Phaser.Math.Clamp(p.x,65,7420);if(!unlocked[3]&&p.x>2600){p.x=2600;say('A triple seal. The grove still glows ←',1)}if(!unlocked[4]&&p.x>4780){p.x=4780;say('Four sockets. Find the four sparks ←',1)}if(mini.hp>0&&p.x>5470)p.x=5470;
 for(let d of drops){if(d.status==='cooldown'&&active>=d.readyAt){d.status='ready';tone(880,.25);log('drop-respawn',{factor:d.n,attempt:d.attempt});say('✦ A familiar glow returns',2)}if(d.status==='ready'&&Math.abs(p.x-d.x)<55)activate(d)}if(trial&&Math.abs(p.x-trial.x)>285)fail(trial);if(use){if(trial)commit();else{let d=drops.find(d=>Math.abs(d.x-p.x)<200&&d.status==='ready');if(d)activate(d)}use=false}
 fireCD-=dt;if((held.has('fire')||auto||fireEdge)&&fireCD<=0&&(!trial||fireEdge)){this.fire();fireEdge=false;}
 for(let h of this.pickups)if(!h.taken&&Math.abs(p.x-h.x)<36){h.taken=true;h.sprite.setVisible(false);health=Math.min(5,health+1);burst(h.x,363,0xffb5ae,20);tone(830);hud()}for(let e of this.enemies){if(e.hp<=0)continue;e.y+=Math.sin(clock*2+e.home)*dt*12;if(Math.abs(e.x-p.x)<35&&Math.abs(e.y-(p.y-40))<60)hurt();}
 for(let b of[mini,boss]){b.hit=Math.max(0,b.hit-dt);if(b.hp<=0||Math.abs(p.x-b.x)>820)continue;b.clock+=dt;let cycle=b.clock%4;if(cycle>2.7&&!b.sent){b.sent=true;hazards.push({x:b.x-70,y:FLOOR-17,vx:-230,life:4});tone(190,.2)}if(cycle<1)b.sent=false;}
 for(let h of hazards){h.x+=h.vx*dt;h.life-=dt;if(Math.abs(h.x-p.x)<28&&Math.abs(h.y-(p.y-25))<35){h.life=0;hurt()}}hazards=hazards.filter(h=>h.life>0);
 for(let s of shots){s.x+=s.vx*dt;s.y+=s.vy*dt;s.life-=dt;let e=this.enemies.find(e=>e.hp>0&&Math.hypot(e.x-s.x,e.y-s.y)<31);if(e){e.hp=0;e.sprite.setVisible(false);s.life=0;burst(e.x,e.y,C[s.n],20);tone(220,.09)}if(s.life>0&&s.b&&s.b.hp>0&&Math.hypot(s.x-(s.b.x-20),s.y-(s.b===boss?265:305))<48){s.life=0;if(s.lead)this.hitBoss(s.b,s)}}shots=shots.filter(s=>s.life>0);
 if(p.x>6500&&checkpoint<6500){checkpoint=6610;health=5;say('CORE CLASH · Break the shield',3);log('boss-enter');hud()}$('#zone').textContent=p.x>6500?'CORE CLASH':p.x>4900?'THE VAULT APPROACH':p.x>3000?'FOUR WINDS':p.x>1300?'WHISPER GROVE':'THE MOON ROAD';this.cameras.main.scrollX=Phaser.Math.Linear(this.cameras.main.scrollX,(p.x>6500?6550:Phaser.Math.Clamp(p.x-320,0,W-960)),.09);}
 hitBoss(b,s){if(b===mini){if(s.n!==b.n){burst(b.x-30,300,0x8196a8,5);tone(130);return}b.hp--;b.n=b.hp%2?4:3;log('mini-hit',{hp:b.hp,weapon:s.n})}else if(s.emp){b.hp=Math.max(0,b.hp-2);log('boss-hit',{hp:b.hp,damage:2});}else{if(!b.orb&&ammo===0&&!shots.some(s=>s.emp&&s.life>0)){orbChance=Math.min(100,orbChance+10);if(Math.random()*100<orbChance||orbChance===100){b.orb={x:Math.max(6660,p.x+100),n:b.hp>30?3:b.hp>14?4:(Math.floor(b.hp/2)%2?3:4),groups:2+(Math.floor(b.hp/10)%3),loaded:0};orbChance=0;say('Fill the orbiting groups',2);log('boss-orb',{...b.orb})}}burst(b.x-20,265,0x9baec4,7);tone(700,.05);return}b.hit=.2;hitStop=.045;burst(b.x-25,b===boss?265:305,0xffe5ad,30);this.cameras.main.shake(90,.003);tone(100,.15);hud();if(b.hp===0){burst(b.x,290,0xffebad,70);log(b===boss?'victory':'miniboss-defeat');if(b===mini){checkpoint=5530;health=5;say('THE VAULT OPENS →',3)}else{won=true;clear();setTimeout(()=>{$('#cover').hidden=false;$('#cover h1').innerHTML='MOON ROAD CLEARED<br><em>CORE CONQUERED!</em>';$('#cover p').textContent='You found the power. You opened the vault.';$('#cover small').textContent='×3 + ×4 · One connected adventure';$('#start').textContent='PLAY AGAIN ↻'},1600)}}}
 draw(dt){const g=this.g,f=this.fx;g.clear();f.clear();this.bg.tilePositionX=this.cameras.main.scrollX*.16;let anim=clock;let frame=won?11:p.land>0?10:!p.ground?(p.vy<0?7:8):p.fire>0?9:(held.has('left')||held.has('right'))?Math.floor(clock*12)%6:6;this.hero.setPosition(p.x,p.y+7).setFrame(frame).setFlipX(p.face<0).setAlpha(p.inv>0&&Math.floor(clock*15)%2?.45:1);
 for(let x=240;x<W;x+=580){g.fillStyle(0x0b1727,.6);g.fillRect(x,385,9,38);g.fillStyle(0xf4dc95,.2);g.fillCircle(x+4,380,18);g.fillStyle(0xffe5a3);g.fillRect(x,373,8,12)}
 for(let d of drops){d.sprite.setVisible(d.status==='ready'||d.status==='trial').setPosition(d.x,300+Math.sin(anim*3)*6).setRotation(Math.sin(anim)*.1);d.label.setText(d.status==='ready'?'✦ ×'+d.n:d.status==='trial'?'PULL ↑':d.status==='earned'?'✦':'');if(d.status==='trial'){let total=groups(d);for(let row=0;row<total;row++){let cx=d.x+(row-(total-1)/2)*33,cy=230;if(d.attempt%2){cx=d.x+Math.cos(row/total*6.28)*78;cy=235+Math.sin(row/total*6.28)*45}g.fillStyle(0x0b1727,.88);g.fillRoundedRect(cx-13,cy-45,26,d.n*15+7,4);g.lineStyle(2,C[d.n],.7);g.strokeRoundedRect(cx-13,cy-45,26,d.n*15+7,4);for(let i=0;i<d.n;i++){g.fillStyle(row<d.loaded?C[d.n]:0x233749);g.fillCircle(cx,cy-35+i*15,5);g.lineStyle(1,C[d.n],.9);g.strokeCircle(cx,cy-35+i*15,5)}}}}
 for(let [x,n]of[[2620,3],[4800,4]])if(!unlocked[n]){g.fillStyle(C[n],.12);g.fillRect(x,205,12,217);for(let i=0;i<n;i++){g.lineStyle(3,C[n],.8);g.strokeCircle(x+6,270+i*28,8)}}
 for(let b of[mini,boss]){let cycle=b.clock%4,fr=b.hp<=0?7:b.hit>0?5:cycle>2.7&&cycle<3?2:cycle>2.1&&cycle<2.7?1:cycle>=3&&cycle<3.4?3:0;b.sprite.setFrame(fr).setAlpha(b.hp<=0?.2:1).setY(402+Math.sin(anim*2)*4);if(b.hp>0){if(b===boss){g.fillStyle(0xd3e6e4,.06);g.fillCircle(b.x-20,265,49);g.lineStyle(2,0xcde2df,.7);g.strokeCircle(b.x-20,265,23+Math.sin(anim*3)*2);g.fillStyle(b.hit>0?0xffe4a1:0xc7dbdb);g.fillPoints([{x:b.x-20,y:251},{x:b.x-6,y:265},{x:b.x-20,y:279},{x:b.x-34,y:265}],true)}let n=b===mini?b.n:0;for(let i=0;i<n;i++){let a=-Math.PI/2+i*6.28/n;g.fillStyle(C[n]);g.fillCircle(b.x+Math.cos(a)*80,285+Math.sin(a)*65,9)}if(cycle>2.1&&cycle<2.7){g.fillStyle(0xffd799,.6);g.fillRect(b.x-650,FLOOR-4,560,3)}}}
 if(boss.orb){let o=boss.orb;for(let j=0;j<o.groups;j++)for(let i=0;i<o.n;i++){let a=i/o.n*6.28+anim*.4,x=o.x+(j-(o.groups-1)/2)*58+Math.cos(a)*19,y=280+Math.sin(a)*19;g.fillStyle(j<o.loaded?0xffe7a6:C[o.n],j<o.loaded?1:.5);g.fillCircle(x,y,6)}g.lineStyle(1,0xffdf9e,.5);g.strokeEllipse(o.x,280,o.groups*62,60)}
 for(let e of this.enemies)if(e.hp>0)e.sprite.setY(e.y).setFrame(Math.floor(anim+e.home)%4===0?1:0);
 for(let s of shots){f.lineStyle(s.emp?7:3,s.emp?0xffe5a3:C[s.n]);f.lineBetween(s.x-s.vx*.025,s.y-s.vy*.025,s.x,s.y);f.fillStyle(0xfff8d7);f.fillCircle(s.x,s.y,s.emp?4:2)}for(let h of hazards){f.lineStyle(4,0xf1c9a2);f.strokeCircle(h.x,h.y,17);f.fillStyle(0xffebc1);f.fillRect(h.x-3,h.y-12,6,24)}if(p.fire>0){f.fillStyle(C[weapon]);f.fillTriangle(p.x+p.face*42,p.y-56,p.x+p.face*65,p.y-46,p.x+p.face*42,p.y-37)}
 for(let q of particles){if(!paused){q.life-=dt;q.x+=q.vx*dt;q.y+=q.vy*dt;q.vy+=180*dt}f.fillStyle(q.c,Math.max(0,q.life));f.fillRect(q.x,q.y,4,4)}particles=particles.filter(q=>q.life>0);for(let i=0;i<35;i++){let x=this.cameras.main.scrollX+(i*83+anim*8)%960,y=180+(i*57)%235;f.fillStyle(0xc6e4c8,.3);f.fillRect(x,y,2,2)} }
}
new Phaser.Game({type:Phaser.AUTO,width:960,height:540,parent:'world',pixelArt:true,roundPixels:true,backgroundColor:'#101c31',audio:{noAudio:true},scene:Level,banner:false});
})();
